import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static final Path FILE = Paths.get("stok.csv");

    static void simpan(List<String[]> data) throws IOException {
        List<String> baris = new ArrayList<>();
        for (String[] d : data) {
            baris.add(String.join(";", d));
        }
        Files.write(FILE, baris);
    }

    static List<String[]> muat() throws IOException {
        List<String[]> data = new ArrayList<>();
        if (!Files.exists(FILE)) {
            return data;
        }
        for (String b : Files.readAllLines(FILE)) {
            data.add(b.split(";"));
        }
        return data;
    }

    public static void main(String[] args) throws IOException {
        List<String[]> data = new ArrayList<>();
        data.add(new String[]{"Kopi", "12", "15000"});
        data.add(new String[]{"Teh", "7", "8000"});
        simpan(data);

        for (String[] d : muat()) {
            System.out.println(d[0] + ": stok " + d[1]);
        }
    }
}

